import { spreadsheetValue } from "./safety.ts";

// Quote cells containing delimiters, quotes or line breaks so they stay in one column (RFC 4180).
function csvCell(value: string): string {
  return /[",\r\n]/.test(value) ? '"' + value.replaceAll('"', '""') + '"' : value;
}

export function csvRecord(values: string[]): string {
  const cells = values.map(value => csvCell(spreadsheetValue(value)));
  // Serialize one record.
  return cells.join(",") + "\r\n";
}
EOF
